PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS learning_summary_attempts (
  id TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  content_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,
  skill_type TEXT NOT NULL CHECK(skill_type IN ('reading','listening')),
  summary_text TEXT NOT NULL,
  word_count INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'evaluating' CHECK(status IN ('evaluating','reviewed','failed')),
  score INTEGER,
  passed INTEGER NOT NULL DEFAULT 0,
  feedback_json TEXT,
  generation_job_id TEXT,
  revision_of_summary_id TEXT REFERENCES learning_summary_attempts(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reviewed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_summary_child_content ON learning_summary_attempts(child_id,content_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_summary_status ON learning_summary_attempts(status,created_at);

INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,source_content_id,curriculum_version_id,generation_model,marks) VALUES ('cloze-r14-p1p4-01','cloze_vocabulary','P1-P4',1,'{"title":"Living Things And Classification","passage":"During a class exploration about living things and classification, the students collected observations and discussed what they meant. Their teacher asked them to choose the most precise word so that the explanation would be clear. The key idea was ___ .","prompt":"Choose the best word or phrase to complete the passage.","options":["organisms","machines","minerals","signals"]}','{"correctOption":0}','{"text":"‘organisms’ best matches the meaning and context of this passage about living things and classification."}','published',NULL,'SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.9-r14',1);
